<template>
  <section class="nw-contact" aria-label="Message FundThred">
    <div><p class="eyebrow">A real team behind your practice</p><h2>{{ agencyId ? 'Message FundThred' : 'Questions? Let’s get your practice started.' }}</h2><p>Ask about NoteWorthy, get help setting up, or explore Auricwell’s connected EHR. Your message goes to our team’s ticket queue.</p></div>
    <p v-if="error" class="nw-alert nw-alert-error" role="alert">{{ error }}</p><p v-if="notice" class="nw-alert" role="status">{{ notice }}</p>
    <template v-if="agencyId"><div class="nw-inline-actions"><label>Conversation<select v-model="selected"><option value="">Start a new conversation</option><option v-for="thread in threads" :key="thread.id" :value="thread.id">{{ thread.subject }} · {{ thread.status }}</option></select></label><button type="button" :disabled="busy" @click="load">Refresh replies</button></div><div v-if="currentThread" class="nw-contact-messages" role="log" aria-live="polite"><article v-for="entry in currentThread.messages" :key="entry.id" :class="entry.sender"><strong>{{ entry.sender==='practice'?'Your practice':'FundThred team' }}</strong><p>{{ entry.body }}</p><small>{{ formatDate(entry.createdAt) }}</small></article><p v-if="!currentThread.messages.length">No public replies yet.</p></div></template>
    <div v-if="saved && !agencyId" class="nw-contact-next"><h3>Inquiry received. Ready to try it?</h3><p>We saved your message as ticket #{{ saved.ticketId }}. Create your free account now, or wait for our team to follow up. Your 30-day trial starts after guided activation.</p><button type="button" :disabled="busy || accountRequested" @click="startAccount">{{ accountRequested ? 'Verification requested — check your email' : 'Create my free trial account' }}</button><router-link to="/fundthred/noteworthy/app">Already have an account? Sign in →</router-link></div>
    <form v-else @submit.prevent="send">
      <template v-if="!agencyId"><div class="nw-form-pair"><label>First name<input v-model.trim="form.firstName" required maxlength="100" autocomplete="given-name" /></label><label>Last name<input v-model.trim="form.lastName" required maxlength="100" autocomplete="family-name" /></label></div><div class="nw-form-pair"><label>Practice name<input v-model.trim="form.practiceName" required maxlength="160" autocomplete="organization" /></label><label>Work email<input v-model.trim="form.email" required type="email" maxlength="254" autocomplete="email" /></label></div></template>
      <label v-if="!selected">I’d like to discuss<select v-model="form.category"><option value="setup">Getting started & the free trial</option><option value="question">A NoteWorthy question</option><option value="auricwell">Auricwell’s EHR for my practice</option><option v-if="agencyId" value="continue">Continuing after my trial</option></select></label>
      <label>Your message<textarea v-model.trim="form.message" required maxlength="3000" rows="4" placeholder="Tell us about your practice and what you want to make easier." /></label><p class="nw-small">Leave out patient names, clinical notes, and other patient information. This is a practice support conversation.</p>
      <div class="nw-contact-trap" aria-hidden="true"><label>Leave empty<input v-model="form.websiteTrap" tabindex="-1" autocomplete="off" /></label></div>
      <label v-if="!agencyId" class="nw-contact-consent"><input v-model="form.consent" type="checkbox" required /> I agree that FundThred / Plot Twist Co. may contact me about this request.</label>
      <button class="nw-submit" :disabled="busy">{{ busy ? 'Saving your message…' : 'Send to FundThred' }}</button><p class="nw-small">Replies appear here for signed-in practices. We’ll follow up on public inquiries using the contact details you provide.</p>
    </form>
  </section>
</template>
<script setup>
import {computed,onMounted,onBeforeUnmount,reactive,ref,watch} from 'vue';
import api from '../../services/api';
const props=defineProps({agencyId:{type:[Number,String],default:null},initialCategory:{type:String,default:'setup'}});
const form=reactive({firstName:'',lastName:'',practiceName:'',email:'',category:props.initialCategory,message:'',websiteTrap:'',consent:false});
const busy=ref(false),error=ref(''),notice=ref(''),saved=ref(null),accountRequested=ref(false),threads=ref([]),selected=ref('');
const currentThread=computed(()=>threads.value.find(t=>t.id===selected.value));
const config={headers:{'X-Noteworthy-Request':'1'},skipGlobalLoading:true};let requestId='',lastPayload='',generation=0,timer;
const formatDate=value=>value?new Date(value).toLocaleString():'';
async function load(){if(!props.agencyId)return;const current=++generation;try{const {data}=await api.get(`/noteworthy/practices/${props.agencyId}/support`,{skipGlobalLoading:true});if(current===generation)threads.value=data.threads || [];}catch(e){if(current===generation)error.value=e.response?.data?.error?.message || 'We could not load replies. Please try again.';}}
async function send(){if(busy.value)return;busy.value=true;error.value='';notice.value='';const current=generation;
  const payload=props.agencyId?{message:form.message,category:form.category,...(selected.value?{threadId:selected.value}:{})}:{name:`${form.firstName} ${form.lastName}`,practiceName:form.practiceName,email:form.email,category:form.category,message:form.message,consent:form.consent,websiteTrap:form.websiteTrap};
  const signature=JSON.stringify(payload);if(signature!==lastPayload){lastPayload=signature;requestId=crypto.randomUUID();}
  try{const {data}=await api.post(props.agencyId?`/noteworthy/practices/${props.agencyId}/${form.category==='continue'&&!selected.value?'continue':'support'}`:'/noteworthy/inquiries',{...payload,requestId},config);if(current!==generation)return;saved.value=data;notice.value='Message saved to FundThred’s ticket queue.';form.message='';lastPayload='';if(props.agencyId){await load();selected.value=data.id || data.messageReference || selected.value;}}
  catch(e){if(current===generation)error.value=e.response?.data?.error?.message || 'We could not confirm your message. Please retry; the same draft reference is preserved.';}finally{busy.value=false;}}
async function startAccount(){if(busy.value)return;busy.value=true;error.value='';try{const {data}=await api.post('/noteworthy/signup',{practiceName:form.practiceName,firstName:form.firstName,lastName:form.lastName,email:form.email,plan:'essential'},config);accountRequested.value=true;notice.value=data.message || 'Use your email verification link to choose your password.';}catch(e){error.value=e.response?.data?.error?.message || 'Account setup could not be confirmed. Please use Create a practice to retry.';}finally{busy.value=false;}}
watch(()=>props.initialCategory,value=>{if(['setup','question','continue','auricwell'].includes(value))form.category=value;});
watch(()=>props.agencyId,()=>{generation++;threads.value=[];selected.value='';saved.value=null;error.value='';notice.value='';load();});
onMounted(()=>{load();if(props.agencyId)timer=setInterval(()=>{if(!document.hidden&&!busy.value)load();},15000);});
onBeforeUnmount(()=>{generation++;clearInterval(timer);});
</script>
<style scoped>
.nw-contact{background:white;border:1px solid #dce7ee;border-radius:20px;padding:30px;color:#071938;font:14px/1.65 Inter,sans-serif;min-width:0}.nw-contact h2{font:800 25px/1.25 Montserrat,sans-serif;letter-spacing:-.04em}.nw-contact h3{font-size:20px}.nw-contact label{display:flex;flex-direction:column;gap:7px;font-size:13px;font-weight:600;margin:15px 0}.nw-contact input,.nw-contact textarea,.nw-contact select{font:inherit;padding:12px;border:1px solid #bfd2df;border-radius:9px;color:#071938;min-width:0;max-width:100%;background:white}.nw-contact button{border:0;border-radius:9px;background:#087f83;color:white;padding:12px 18px;font:700 13px Inter,sans-serif;cursor:pointer}.nw-contact button:disabled{opacity:.55;cursor:wait}.nw-contact a{color:#087f83}.nw-contact .nw-form-pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.nw-contact .nw-submit{width:100%;margin:15px 0}.nw-contact-consent{flex-direction:row!important;align-items:start}.nw-contact-consent input{margin-top:6px}.nw-contact-trap{position:absolute;left:-9999px}.nw-contact-next{background:#e9f7ef;padding:24px;border-radius:14px}.nw-contact-next a{display:block;margin-top:15px}.nw-contact-messages{max-height:500px;overflow:auto;padding:10px;background:#f4f8fa;border-radius:12px}.nw-contact-messages article{padding:15px;border-radius:10px;background:white;margin:12px 0;max-width:90%}.nw-contact-messages article.practice{margin-left:auto;background:#e3f3ef}.nw-contact-messages p{white-space:pre-wrap;overflow-wrap:anywhere;margin:6px 0}.nw-contact-messages small{font-size:11px;color:#536d80}.nw-contact .nw-inline-actions{display:flex;gap:16px;align-items:center;flex-wrap:wrap}.nw-contact .nw-alert{padding:15px;background:#e8f7ed;color:#175a42;border-radius:10px}.nw-contact .nw-alert-error{background:#fff0ef;color:#9b3030}.nw-contact :focus-visible{outline:3px solid #8bdda6;outline-offset:3px}@media(max-width:650px){.nw-contact{padding:20px}.nw-contact .nw-form-pair{grid-template-columns:1fr;gap:0}}
</style>
